export function buildMindTools({ DIST, DOMAIN, renderPage, writeFileSync, join, ensureDir }) {
  console.log('  🔨 Building Psychological Archetypes & Intelligence Types Suite (500 tools)...');
  const outDir = join(DIST, 'mind');
  ensureDir(outDir);

  let builtCount = 0;

  MIND_TOOLS.forEach(tool => {
    const filePath = join(outDir, tool.slug + '.html');
    const canonical = DOMAIN + '/mind/' + tool.slug;

    const sliderMarkup = tool.sliders.map(s => {
      return '<div style="margin-bottom:1rem;">' +
        '<div style="display:flex;justify-content:space-between;font-family:var(--mono);font-size:0.85rem;margin-bottom:0.35rem;">' +
          '<span>' + s.label + '</span>' +
          '<strong id="val_' + s.id + '">' + s.val + '/10</strong>' +
        '</div>' +
        '<input type="range" id="rng_' + s.id + '" min="' + s.min + '" max="' + s.max + '" value="' + s.val + '" oninput="calcMindProfile()" style="width:100%;accent-color:#6366f1;">' +
      '</div>';
    }).join('');

    const faqMarkup = tool.faq.map(f => {
      return '<details style="border:1px solid var(--border);border-radius:4px;margin-bottom:0.5rem;background:var(--surface);">' +
        '<summary style="padding:0.85rem 1rem;cursor:pointer;font-family:var(--serif);font-size:1.05rem;font-weight:600;color:var(--fg);">' + f.q + '</summary>' +
        '<div style="padding:0.75rem 1rem 1rem;font-size:0.95rem;line-height:1.6;color:var(--text-muted);border-top:1px solid var(--border);background:var(--surface-alt);">' + f.a + '</div>' +
      '</details>';
    }).join('');

    const bodyHtml = '<div class="article-container" style="max-width:900px;">' +
      '<nav style="font-family:var(--mono);font-size:0.8rem;margin-bottom:1.5rem;color:var(--text-muted);">' +
        '<a href="/">Home</a> &gt; <a href="/mind/">Mind & Intelligence</a> &gt; ' + tool.title.split('[')[0].trim() +
      '</nav>' +
      '<div style="display:flex;gap:0.5rem;align-items:center;margin-bottom:0.5rem;flex-wrap:wrap;">' +
        '<span class="badge badge-green">100% Free & No Sign-Up</span>' +
        '<span class="badge badge-purple">' + tool.categoryName + '</span>' +
        '<span class="badge badge-amber">Archetype: ' + tool.archetype + '</span>' +
      '</div>' +
      '<h1 style="font-family:var(--serif);font-size:2rem;margin-bottom:0.5rem;line-height:1.25;">' + tool.title + '</h1>' +
      '<p style="color:var(--text-muted);font-size:0.95rem;line-height:1.6;margin-bottom:1.5rem;">' + tool.metaDesc + '</p>' +
      '<div class="tool-box" style="background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:1.5rem;margin-bottom:2rem;">' +
        '<h3 style="font-family:var(--serif);font-size:1.2rem;margin-bottom:1rem;">Self-Assessment Trait Ratings (1 = Low, 10 = Exceptional)</h3>' +
        '<div style="display:grid;gap:1.25rem;margin-bottom:1.5rem;">' + sliderMarkup + '</div>' +
        '<div id="mind-results-card" style="background:var(--surface-alt);border:1px solid var(--border);border-radius:6px;padding:1.25rem;margin-top:1.5rem;">' +
          '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:0.5rem;margin-bottom:0.75rem;">' +
            '<span style="font-family:var(--mono);font-size:0.85rem;text-transform:uppercase;color:var(--text-muted);">Composite Trait Index:</span>' +
            '<span id="score-percentile" style="font-family:var(--mono);font-size:1.1rem;font-weight:bold;color:#6366f1;">80% (Superior)</span>' +
          '</div>' +
          '<div style="font-family:var(--serif);font-size:1.35rem;font-weight:700;margin-bottom:0.5rem;color:var(--fg);" id="archetype-name">' + tool.archetype + '</div>' +
          '<p id="archetype-summary" style="font-size:0.95rem;line-height:1.6;color:var(--text);margin-bottom:1rem;">Loading cognitive profile...</p>' +
          '<div style="border-top:1px solid var(--border);padding-top:0.75rem;font-size:0.85rem;color:var(--text-muted);line-height:1.5;">' +
            '<strong>High Alignment Fields:</strong> ' + tool.careerField +
          '</div>' +
        '</div>' +
        '<div style="display:flex;gap:0.75rem;margin-top:1.25rem;flex-wrap:wrap;">' +
          '<button type="button" class="btn-primary" onclick="copyMindResult()" style="padding:0.5rem 1rem;font-size:0.85rem;">📋 Copy Diagnostic Summary</button>' +
          '<button type="button" class="btn-sec" onclick="randomizeSliders()" style="padding:0.5rem 1rem;font-size:0.85rem;">🎲 Random Sample Profile</button>' +
        '</div>' +
      '</div>' +
      '<div style="margin:2.5rem 0;">' +
        '<h2 style="font-family:var(--serif);font-size:1.4rem;margin-bottom:1rem;">Frequently Asked Questions</h2>' + faqMarkup +
      '</div>' +
    '</div>' +
    '<script>' +
      'var sliderIds = ' + JSON.stringify(tool.sliders.map(s => s.id)) + ';' +
      'var archetypeBase = ' + JSON.stringify(tool.archetype) + ';' +
      'function calcMindProfile() {' +
        'var sum = 0;' +
        'sliderIds.forEach(function(id) {' +
          'var el = document.getElementById("rng_" + id);' +
          'var v = el ? parseInt(el.value, 10) : 5;' +
          'var lbl = document.getElementById("val_" + id);' +
          'if (lbl) lbl.textContent = v + "/10";' +
          'sum += v;' +
        '});' +
        'var max = sliderIds.length * 10;' +
        'var pct = Math.round((sum / max) * 100);' +
        'var tier = "Emergent";' +
        'if (pct >= 85) tier = "Exceptional Mastery";' +
        'else if (pct >= 70) tier = "High Natural Aptitude";' +
        'else if (pct >= 50) tier = "Balanced Functional Range";' +
        'else tier = "Latent / Undeveloped";' +
        'var pDisp = document.getElementById("score-percentile");' +
        'if (pDisp) pDisp.textContent = pct + "% (" + tier + ")";' +
        'var sumBox = document.getElementById("archetype-summary");' +
        'if (sumBox) {' +
          'if (pct >= 75) {' +
            'sumBox.textContent = "Your responses reflect pronounced cognitive dominance as " + archetypeBase + ". You exhibit profound intuitive fluency, fast pattern synthesis, and resilience under complex problem-solving conditions.";' +
          '} else if (pct >= 50) {' +
            'sumBox.textContent = "Your cognitive profile indicates adaptable versatility as " + archetypeBase + ". You balance specialized trait intuition with pragmatic contextual flexibility, allowing dynamic task shifting.";' +
          '} else {' +
            'sumBox.textContent = "Your responses reflect latent or developing expression of " + archetypeBase + ". Focused deliberate practice and reducing environmental friction will unlock significant reserve capacity.";' +
          '}' +
        '}' +
      '}' +
      'function copyMindResult() {' +
        'var pDisp = document.getElementById("score-percentile");' +
        'var text = "Diagnostic Result: " + (pDisp ? pDisp.textContent : "") + " | Archetype: " + archetypeBase + " | Digital Tools Shed (digitaltoolsshed.com)";' +
        'navigator.clipboard.writeText(text);' +
        'alert("Diagnostic summary copied to clipboard!");' +
      '}' +
      'function randomizeSliders() {' +
        'sliderIds.forEach(function(id) {' +
          'var el = document.getElementById("rng_" + id);' +
          'if (el) el.value = Math.floor(Math.random() * 8) + 3;' +
        '});' +
        'calcMindProfile();' +
      '}' +
      'document.addEventListener("DOMContentLoaded", calcMindProfile);' +
    '</script>';

    const html = renderPage({
      title: tool.title,
      metaDesc: tool.metaDesc,
      canonical: canonical,
      currentPath: '/mind/' + tool.slug,
      bodyContent: bodyHtml,
      faq: tool.faq,
      breadcrumbs: [
        { name: 'Home', url: '/' },
        { name: 'Mind & Intelligence', url: '/mind/' },
        { name: tool.title.split('[')[0].trim(), url: canonical }
      ]
    });

    writeFileSync(filePath, html, 'utf8');
    builtCount++;
  });

  // Build the Mind Suite Hub Page at /mind/index.html
  const hubListHtml = MIND_TOOLS.map(t => {
    return '<a href="/mind/' + t.slug + '" style="display:block;padding:1rem;background:var(--surface);border:1px solid var(--border);border-radius:6px;text-decoration:none;color:inherit;transition:transform 0.15s ease,border-color 0.15s ease;">' +
      '<span class="badge badge-purple" style="font-size:0.7rem;margin-bottom:0.4rem;display:inline-block;">' + t.categoryName.split('&')[0].trim() + '</span>' +
      '<div style="font-family:var(--serif);font-size:1rem;font-weight:600;line-height:1.3;margin-bottom:0.35rem;color:var(--fg);">' + t.title.split('[')[0].trim() + '</div>' +
      '<p style="font-size:0.8rem;color:var(--text-muted);margin:0;line-height:1.4;">Archetype: ' + t.archetype + ' &bull; ' + t.careerField.split(',')[0] + '</p>' +
    '</a>';
  }).join('');

  const hubBody = '<div class="article-container" style="max-width:1000px;">' +
    '<nav style="font-family:var(--mono);font-size:0.8rem;margin-bottom:1.5rem;color:var(--text-muted);">' +
      '<a href="/">Home</a> &gt; Mind & Psychological Archetypes Hub' +
    '</nav>' +
    '<div style="display:flex;gap:0.5rem;align-items:center;margin-bottom:0.5rem;">' +
      '<span class="badge badge-green">500 Free Tools</span>' +
      '<span class="badge badge-purple">Zero Signup</span>' +
      '<span class="badge badge-amber">Private & Client-Side</span>' +
    '</div>' +
    '<h1 style="font-family:var(--serif);font-size:2.2rem;margin-bottom:0.5rem;">Mind & Psychological Archetypes Hub</h1>' +
    '<p style="color:var(--text-muted);font-size:1rem;line-height:1.6;margin-bottom:2rem;">' +
      'Comprehensive directory of 500 evidence-informed cognitive assessments, multiple intelligence evaluations, neurodivergent profile analyzers, and behavioral archetype diagnostics.' +
    '</p>' +
    '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:1rem;">' + hubListHtml + '</div>' +
  '</div>';

  const hubHtml = renderPage({
    title: 'Mind & Psychological Archetypes Hub — 500 Free Cognitive Tools [Instant Diagnostics]',
    metaDesc: 'Explore 500 free psychological diagnostics, intelligence type calculators, neurotype assessments, and cognitive bias audits. 100% free, private, and instant.',
    canonical: DOMAIN + '/mind/',
    currentPath: '/mind/',
    bodyContent: hubBody,
    breadcrumbs: [
      { name: 'Home', url: '/' },
      { name: 'Mind & Intelligence Hub', url: '/mind/' }
    ]
  });

  writeFileSync(join(outDir, 'index.html'), hubHtml, 'utf8');
  console.log('  ✓ Built Mind & Intelligence Suite (500 tools + hub in /mind/)');
}
